package main

import (
	"fmt"
	"strings"
)

// renderCLISelfClient emits internal/client/client.go for --from-openapi
// mode: a self-contained HTTP client mirroring the generated SDK's
// surface (NewClient, Client.Token, APIError) so the shared CLI
// scaffolding (parseGlobals, apiFail, custom.go) works unchanged, plus
// DoRaw for operations whose bodies or responses aren't JSON.
func renderCLISelfClient(spec cliSpec) string {
	return `// Package client is the ` + spec.Binary + ` CLI's self-contained HTTP
// client, generated by ` + "`gofastr generate cli --from-openapi`" + `. The code
// is yours to own and edit.
package client

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
)

// tokenHeader / tokenPrefix come from the spec's security scheme:
// "Authorization" + "Bearer " for http bearer, or the apiKey header
// name with no prefix.
const (
	tokenHeader = ` + fmt.Sprintf("%q", spec.TokenHeader) + `
	tokenPrefix = ` + fmt.Sprintf("%q", spec.TokenPrefix) + `
)

// Client sends requests against the API's base URL. Pass any
// *http.Client (httptest, retryable wrapper, ...): Client never closes
// it. Token, when set, is sent on every request via the header above.
type Client struct {
	BaseURL string
	HTTP    *http.Client
	Token   string
}

// NewClient constructs a Client with the default http.Client when one
// is not supplied. BaseURL should NOT include a trailing slash.
func NewClient(baseURL string, httpClient *http.Client) *Client {
	if httpClient == nil {
		httpClient = http.DefaultClient
	}
	return &Client{BaseURL: baseURL, HTTP: httpClient}
}

// APIError is returned for non-2xx responses. Status is the HTTP code;
// Body holds the raw response so callers can decode application-level
// error fields.
type APIError struct {
	Status int
	Body   []byte
}

func (e *APIError) Error() string {
	return fmt.Sprintf("api: %d: %s", e.Status, string(e.Body))
}

// BatchResponse / BatchResult mirror the entity SDK's batch envelope.
// The OpenAPI CLI generates no batch verbs; the shared output helpers
// reference the types, so they exist for compatibility (and for
// custom.go commands that talk to a gofastr batch endpoint).
type BatchResponse struct {
	Committed bool          ` + "`json:\"committed\"`" + `
	Results   []BatchResult ` + "`json:\"results\"`" + `
}

// BatchResult is one entry in a batch response, in input order.
type BatchResult struct {
	Index   int                 ` + "`json:\"index\"`" + `
	Data    map[string]any      ` + "`json:\"data,omitempty\"`" + `
	Error   string              ` + "`json:\"error,omitempty\"`" + `
	Fields  map[string][]string ` + "`json:\"fields,omitempty\"`" + `
	Skipped bool                ` + "`json:\"skipped,omitempty\"`" + `
}

// Do sends method+path with an optional JSON body and decodes the 2xx
// response into out. Non-2xx returns *APIError; transport errors pass
// through. Kept signature-compatible with the entity SDK's Do so
// custom.go recipes transfer between the two CLI flavors.
func (c *Client) Do(ctx context.Context, method, path string, body, out any) error {
	var reqBody io.Reader
	contentType := ""
	if body != nil {
		buf, err := json.Marshal(body)
		if err != nil {
			return fmt.Errorf("marshal: %w", err)
		}
		reqBody = bytes.NewReader(buf)
		contentType = "application/json"
	}
	data, _, err := c.DoRaw(ctx, method, path, nil, nil, contentType, reqBody)
	if err != nil {
		return err
	}
	if out == nil || len(data) == 0 {
		return nil
	}
	return json.Unmarshal(data, out)
}

// DoRaw is the transport under Do: query and extra headers ride along,
// the body streams as-is under contentType, and the raw response bytes
// come back with the response Content-Type. Operations with binary
// bodies or non-JSON responses (an image, a CSV) go through here.
func (c *Client) DoRaw(ctx context.Context, method, path string, query url.Values, hdr http.Header, contentType string, body io.Reader) ([]byte, string, error) {
	u := c.BaseURL + path
	if len(query) > 0 {
		u += "?" + query.Encode()
	}
	req, err := http.NewRequestWithContext(ctx, method, u, body)
	if err != nil {
		return nil, "", err
	}
	for k, vs := range hdr {
		for _, v := range vs {
			req.Header.Add(k, v)
		}
	}
	if contentType != "" {
		req.Header.Set("Content-Type", contentType)
	}
	if c.Token != "" {
		req.Header.Set(tokenHeader, tokenPrefix+c.Token)
	}

	resp, err := c.HTTP.Do(req)
	if err != nil {
		return nil, "", err
	}
	defer resp.Body.Close()
	data, err := io.ReadAll(resp.Body)
	if err != nil {
		return nil, "", err
	}
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return nil, "", &APIError{Status: resp.StatusCode, Body: data}
	}
	return data, resp.Header.Get("Content-Type"), nil
}
`
}

// renderCLIOpsFile emits operations.go: one command per OpenAPI
// operation plus the shared plumbing they need.
func renderCLIOpsFile(spec cliSpec) string {
	needsStrconv := false
	needsFmt := false
	needsMulti := false
	for _, op := range spec.Ops {
		all := append(append(append([]cliOpParam{}, op.PathParams...), op.QueryParams...), op.HeaderParams...)
		for _, p := range all {
			if p.GoType != "string" && !p.Repeated {
				needsStrconv = true
			}
			if p.Repeated {
				needsMulti = true
			}
			if p.Required {
				needsFmt = true
			}
		}
		if op.BodyKind == "binary" {
			needsFmt = true
		}
		if op.BodyKind == "json" {
			for _, f := range op.BodyFields {
				if f.Required {
					needsFmt = true
				}
			}
		}
	}

	needsFlag := false
	for _, op := range spec.Ops {
		if opNeedsVisited(op) {
			needsFlag = true
		}
	}

	needsBody := false
	for _, op := range spec.Ops {
		if op.BodyKind == "json" || op.BodyKind == "raw" {
			needsBody = true
		}
	}

	var sb strings.Builder
	sb.WriteString("package main\n\nimport (\n")
	if needsBody {
		sb.WriteString("\t\"bytes\"\n")
	}
	sb.WriteString("\t\"encoding/json\"\n")
	if needsFlag {
		sb.WriteString("\t\"flag\"\n")
	}
	if needsFmt {
		sb.WriteString("\t\"fmt\"\n")
	}
	if needsBody {
		sb.WriteString("\t\"io\"\n")
	}
	sb.WriteString("\t\"net/http\"\n\t\"net/url\"\n\t\"os\"\n")
	if needsStrconv {
		sb.WriteString("\t\"strconv\"\n")
	}
	sb.WriteString("\t\"strings\"\n)\n\n")
	if needsMulti {
		sb.WriteString(`// multiFlag collects a repeatable flag (spec: array-of-scalar parameter).
type multiFlag []string

func (m *multiFlag) String() string { return strings.Join(*m, ",") }
func (m *multiFlag) Set(v string) error { *m = append(*m, v); return nil }

`)
	}
	sb.WriteString(`// printResponse renders an operation response: JSON pretty-prints,
// anything else (an image, CSV, plain text) streams raw to stdout so
// redirects work: ` + "`" + spec.Binary + " <op> > out.png`" + `.
func printResponse(data []byte, contentType string) int {
	if strings.Contains(contentType, "json") {
		var v any
		if jsonErr := json.Unmarshal(data, &v); jsonErr == nil {
			return printJSON(v)
		}
	}
	_, _ = os.Stdout.Write(data)
	return 0
}

// openBodyFile resolves a --file value: "-" streams stdin.
func openBodyFile(v string) (*os.File, error) {
	if v == "-" {
		return os.Stdin, nil
	}
	return os.Open(v)
}

func operationCommands() []command {
	return []command{
`)
	for _, op := range spec.Ops {
		fmt.Fprintf(&sb, "\t\t{name: %q, summary: %q, run: runOp%s},\n", op.Command, op.Summary, op.GoName)
	}
	sb.WriteString("\t}\n}\n")

	for _, op := range spec.Ops {
		renderCLIOpRunner(&sb, spec, op)
	}
	return sb.String()
}

// opNeedsVisited reports whether a runner consults the set-flags map:
// any required parameter or body field, or any non-repeated query or
// header parameter (sent only when the caller set it).
func opNeedsVisited(op cliOp) bool {
	for _, p := range op.PathParams {
		_ = p
		return true
	}
	for _, p := range append(append([]cliOpParam{}, op.QueryParams...), op.HeaderParams...) {
		if p.Required || !p.Repeated {
			return true
		}
	}
	// A JSON body always consults visited: the body-was-given check
	// walks the field flags.
	return op.BodyKind == "json"
}

// flagDecl emits one parameter's flag declaration into the runner.
func flagDecl(sb *strings.Builder, varName string, p cliOpParam, usage string) {
	if p.Repeated {
		fmt.Fprintf(sb, "\tvar %s multiFlag\n\tfs.Var(&%s, %q, %q)\n", varName, varName, p.Flag, usage+" (repeatable)")
		return
	}
	switch p.GoType {
	case "int":
		fmt.Fprintf(sb, "\t%s := fs.Int(%q, 0, %q)\n", varName, p.Flag, usage)
	case "float64":
		fmt.Fprintf(sb, "\t%s := fs.Float64(%q, 0, %q)\n", varName, p.Flag, usage)
	case "bool":
		fmt.Fprintf(sb, "\t%s := fs.Bool(%q, false, %q)\n", varName, p.Flag, usage)
	default:
		fmt.Fprintf(sb, "\t%s := fs.String(%q, \"\", %q)\n", varName, p.Flag, usage)
	}
}

// paramString emits the expression converting a declared flag var back
// to the string the wire wants.
func paramString(varName string, p cliOpParam) string {
	switch p.GoType {
	case "int":
		return "strconv.Itoa(*" + varName + ")"
	case "float64":
		return "strconv.FormatFloat(*" + varName + ", 'f', -1, 64)"
	case "bool":
		return "strconv.FormatBool(*" + varName + ")"
	default:
		return "*" + varName
	}
}

func renderCLIOpRunner(sb *strings.Builder, spec cliSpec, op cliOp) {
	fmt.Fprintf(sb, "\nfunc runOp%s(args []string) int {\n", op.GoName)
	fmt.Fprintf(sb, "\tfs := newFlagSet(%q)\n", op.Command)

	usage := func(p cliOpParam, kind string) string {
		u := kind + " parameter"
		if p.Required {
			u += " (required)"
		}
		return u
	}
	for i, p := range op.PathParams {
		flagDecl(sb, fmt.Sprintf("pp%d", i), p, usage(p, "path"))
	}
	for i, p := range op.QueryParams {
		flagDecl(sb, fmt.Sprintf("qp%d", i), p, usage(p, "query"))
	}
	for i, p := range op.HeaderParams {
		flagDecl(sb, fmt.Sprintf("hp%d", i), p, usage(p, "header"))
	}
	switch op.BodyKind {
	case "json":
		for i, f := range op.BodyFields {
			u := "body field"
			if f.Required {
				u += " (required)"
			}
			flagDecl(sb, fmt.Sprintf("bf%d", i), cliOpParam{Flag: f.Flag, GoType: f.GoType}, u)
		}
		sb.WriteString("\tjsonF := fs.String(\"json\", \"\", \"raw JSON body (inline, @file, or - for stdin); mutually exclusive with field flags\")\n")
	case "raw":
		sb.WriteString("\tjsonF := fs.String(\"json\", \"\", \"raw JSON body (inline, @file, or - for stdin)\")\n")
	case "binary":
		fmt.Fprintf(sb, "\tfileF := fs.String(\"file\", \"\", \"request body file (%s); - reads stdin (required)\")\n", op.BodyContentType)
	}

	sb.WriteString("\tg, code := parseGlobals(fs, args)\n\tif g == nil {\n\t\treturn code\n\t}\n")
	if opNeedsVisited(op) {
		sb.WriteString("\tvisited := map[string]bool{}\n\tfs.Visit(func(f *flag.Flag) { visited[f.Name] = true })\n")
	}

	// Required checks: path params always, plus flagged query/header/body.
	var required []cliOpParam
	required = append(required, op.PathParams...)
	for _, p := range op.QueryParams {
		if p.Required {
			required = append(required, p)
		}
	}
	for _, p := range op.HeaderParams {
		if p.Required {
			required = append(required, p)
		}
	}
	for _, p := range required {
		fmt.Fprintf(sb, "\tif !visited[%q] {\n\t\tfmt.Fprintln(os.Stderr, \"--%s is required\")\n\t\treturn 2\n\t}\n", p.Flag, p.Flag)
	}
	if op.BodyKind == "json" {
		for _, f := range op.BodyFields {
			if !f.Required {
				continue
			}
			fmt.Fprintf(sb, "\tif *jsonF == \"\" && !visited[%q] {\n\t\tfmt.Fprintln(os.Stderr, \"--%s is required (or pass --json)\")\n\t\treturn 2\n\t}\n", f.Flag, f.Flag)
		}
	}
	if op.BodyKind == "binary" {
		sb.WriteString("\tif *fileF == \"\" {\n\t\tfmt.Fprintln(os.Stderr, \"--file is required\")\n\t\treturn 2\n\t}\n")
	}

	// Path assembly.
	fmt.Fprintf(sb, "\tpath := %q\n", op.PathTemplate)
	for i, p := range op.PathParams {
		fmt.Fprintf(sb, "\tpath = strings.Replace(path, \"{%s}\", url.PathEscape(%s), 1)\n", p.Name, paramString(fmt.Sprintf("pp%d", i), p))
	}

	// Query assembly: only flags the caller actually set are sent.
	sb.WriteString("\tq := url.Values{}\n")
	for i, p := range op.QueryParams {
		v := fmt.Sprintf("qp%d", i)
		if p.Repeated {
			fmt.Fprintf(sb, "\tfor _, item := range %s {\n\t\tq.Add(%q, item)\n\t}\n", v, p.Name)
			continue
		}
		fmt.Fprintf(sb, "\tif visited[%q] {\n\t\tq.Set(%q, %s)\n\t}\n", p.Flag, p.Name, paramString(v, p))
	}

	// Header assembly.
	sb.WriteString("\thdr := http.Header{}\n")
	for i, p := range op.HeaderParams {
		v := fmt.Sprintf("hp%d", i)
		if p.Repeated {
			fmt.Fprintf(sb, "\tfor _, item := range %s {\n\t\thdr.Add(%q, item)\n\t}\n", v, p.Name)
			continue
		}
		fmt.Fprintf(sb, "\tif visited[%q] {\n\t\thdr.Set(%q, %s)\n\t}\n", p.Flag, p.Name, paramString(v, p))
	}

	// Body + request. Bodies are optional unless the spec marks fields
	// required: with no --json and no field flags, nothing is sent.
	switch op.BodyKind {
	case "json":
		flags := make([]string, 0, len(op.BodyFields))
		for _, f := range op.BodyFields {
			flags = append(flags, fmt.Sprintf("%q", f.Flag))
		}
		fmt.Fprintf(sb, "\tbodySet := *jsonF != \"\"\n\tfor _, fl := range []string{%s} {\n\t\tif visited[fl] {\n\t\t\tbodySet = true\n\t\t}\n\t}\n", strings.Join(flags, ", "))
		sb.WriteString("\tct := \"\"\n\tvar rdr io.Reader\n\tif bodySet {\n")
		sb.WriteString("\t\tbody, code := buildBody(fs, *jsonF, func(flagName string, body map[string]any) error {\n\t\t\tswitch flagName {\n")
		for i, f := range op.BodyFields {
			fmt.Fprintf(sb, "\t\t\tcase %q:\n\t\t\t\tbody[%q] = *bf%d\n", f.Flag, f.Wire, i)
		}
		sb.WriteString("\t\t\t}\n\t\t\treturn nil\n\t\t})\n\t\tif code != 0 {\n\t\t\treturn code\n\t\t}\n")
		sb.WriteString("\t\tpayload, err := json.Marshal(body)\n\t\tif err != nil {\n\t\t\treturn apiFail(err)\n\t\t}\n")
		sb.WriteString("\t\tct = \"application/json\"\n\t\trdr = bytes.NewReader(payload)\n\t}\n")
		fmt.Fprintf(sb, "\tdata, respCT, err := g.client.DoRaw(g.ctx, %q, path, q, hdr, ct, rdr)\n", op.Method)
	case "raw":
		sb.WriteString("\tct := \"\"\n\tvar rdr io.Reader\n\tif *jsonF != \"\" {\n\t\tpayload, err := readJSONArg(*jsonF)\n\t\tif err != nil {\n\t\t\treturn apiFail(err)\n\t\t}\n\t\tct = \"application/json\"\n\t\trdr = bytes.NewReader(payload)\n\t}\n")
		fmt.Fprintf(sb, "\tdata, respCT, err := g.client.DoRaw(g.ctx, %q, path, q, hdr, ct, rdr)\n", op.Method)
	case "binary":
		sb.WriteString("\tf, err := openBodyFile(*fileF)\n\tif err != nil {\n\t\treturn apiFail(err)\n\t}\n\tif f != os.Stdin {\n\t\tdefer f.Close()\n\t}\n")
		fmt.Fprintf(sb, "\tdata, respCT, err := g.client.DoRaw(g.ctx, %q, path, q, hdr, %q, f)\n", op.Method, op.BodyContentType)
	default:
		fmt.Fprintf(sb, "\tdata, respCT, err := g.client.DoRaw(g.ctx, %q, path, q, hdr, \"\", nil)\n", op.Method)
	}
	sb.WriteString("\tif err != nil {\n\t\treturn apiFail(err)\n\t}\n\treturn printResponse(data, respCT)\n}\n")
}
